pub(crate) const INVENTORY_KEY: &str = "production.filamentInventory";
const MAX_INVENTORY_BYTES: usize = 2 * 1024 * 1024;
const MAX_NOTICES: usize = 128;
const MAX_NOTICE_BYTES: usize = 4096;

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct FilamentNotice {
    action: String,
    details: String,
}

fn validate_inventory(value: &str, notices: &[FilamentNotice]) -> Result<(), String> {
    if value.len() > MAX_INVENTORY_BYTES {
        return Err("FILAMENT_INVENTORY_TOO_LARGE: учёт пластика превышает 2 МиБ".into());
    }
    let document: serde_json::Value = serde_json::from_str(value)
        .map_err(|_| "FILAMENT_INVENTORY_INVALID: недопустимый JSON".to_string())?;
    if !document.is_object()
        || document.get("schemaVersion").and_then(serde_json::Value::as_u64) != Some(1)
    {
        return Err("FILAMENT_INVENTORY_INVALID: требуется schemaVersion 1".into());
    }
    if notices.len() > MAX_NOTICES {
        return Err("FILAMENT_NOTICES_INVALID: слишком много уведомлений".into());
    }
    for notice in notices {
        if !matches!(notice.action.as_str(), "filament.milestone" | "filament.reserve")
            || notice.details.trim().is_empty()
            || notice.details.len() > MAX_NOTICE_BYTES
        {
            return Err("FILAMENT_NOTICES_INVALID: недопустимое уведомление".into());
        }
    }
    Ok(())
}

// Persist idempotency markers and their notifications together. In particular,
// a failed audit-chain insert must never consume stock without the notice, or
// leave a notice whose corresponding stock/idempotency write was rolled back.
fn commit_inventory(
    connection: &mut Connection,
    role: Role,
    user_id: &str,
    value: &str,
    notices: &[FilamentNotice],
    timestamp: i64,
) -> Result<(), String> {
    if role < Role::Operator {
        return Err("FORBIDDEN: недостаточно прав".into());
    }
    validate_inventory(value, notices)?;
    let transaction = connection
        .transaction_with_behavior(TransactionBehavior::Immediate)
        .map_err(|error| error.to_string())?;
    transaction
        .execute(
            "INSERT INTO kv(key,value,updated_at) VALUES(?1,?2,?3)
             ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",
            params![INVENTORY_KEY, value, timestamp],
        )
        .map_err(|error| error.to_string())?;
    for notice in notices {
        audit_chain::insert(&transaction, timestamp, user_id, &notice.action, &notice.details)?;
    }
    transaction.commit().map_err(|error| error.to_string())
}

#[tauri::command]
pub(crate) fn filament_inventory_commit(
    app: AppHandle,
    auth: State<'_, AuthState>,
    session_token: String,
    value: String,
    notices: Vec<FilamentNotice>,
) -> Result<(), String> {
    let user = require_role(&app, &auth, &session_token, Role::Operator)?;
    commit_inventory(
        &mut open_db(&app)?,
        parse_role(&user.role)?,
        &user.id,
        &value,
        &notices,
        now_ms(),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn database() -> Connection {
        let connection = Connection::open_in_memory().unwrap();
        connection
            .execute_batch(
                "CREATE TABLE kv(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at INTEGER NOT NULL);
                 CREATE TABLE audit(
                     id INTEGER PRIMARY KEY AUTOINCREMENT,ts INTEGER NOT NULL,
                     user TEXT NOT NULL,action TEXT NOT NULL,details TEXT NOT NULL
                 );
                 CREATE TABLE audit_chain(
                     sequence INTEGER PRIMARY KEY AUTOINCREMENT,audit_id INTEGER NOT NULL UNIQUE,
                     previous_hash TEXT NOT NULL,entry_hash TEXT NOT NULL UNIQUE,
                     canonical_version INTEGER NOT NULL,created_at INTEGER NOT NULL
                 );",
            )
            .unwrap();
        connection
    }

    fn notice(action: &str) -> FilamentNotice {
        FilamentNotice {
            action: action.into(),
            details: "K1 Max: 1 кг".into(),
        }
    }

    fn count(connection: &Connection, table: &str) -> i64 {
        connection
            .query_row(&format!("SELECT COUNT(*) FROM {table}"), [], |row| row.get(0))
            .unwrap()
    }

    fn stored(connection: &Connection) -> String {
        connection
            .query_row("SELECT value FROM kv WHERE key=?1", [INVENTORY_KEY], |row| row.get(0))
            .unwrap()
    }

    #[test]
    fn filament_inventory_commits_exact_state_and_both_chained_notices() {
        for role in [Role::Operator, Role::Admin] {
            let mut connection = database();
            let value = "{\"schemaVersion\":1, \"usedGrams\":1000,\"markers\":[\"job-1\"]}";
            commit_inventory(
                &mut connection,
                role,
                "operator",
                value,
                &[notice("filament.milestone"), notice("filament.reserve")],
                7,
            )
            .unwrap();
            assert_eq!(stored(&connection), value);
            assert_eq!(count(&connection, "kv"), 1);
            assert_eq!(count(&connection, "audit"), 2);
            assert_eq!(audit_chain::verify(&connection).unwrap().verified_entries, 2);
        }
    }

    #[test]
    fn filament_inventory_rolls_back_state_and_prior_notice_if_later_chain_insert_fails() {
        let mut connection = database();
        let old = "{\"schemaVersion\":1,\"usedGrams\":0}";
        commit_inventory(&mut connection, Role::Operator, "operator", old, &[], 1).unwrap();
        // The first notice inserts successfully, the second audit row inserts,
        // and then its chain insertion fails: every change must roll back.
        connection
            .execute_batch(
                "CREATE TRIGGER fail_second_chain BEFORE INSERT ON audit_chain
                 WHEN (SELECT COUNT(*) FROM audit_chain)=1
                 BEGIN SELECT RAISE(ABORT,'forced chain failure'); END;",
            )
            .unwrap();
        let result = commit_inventory(
            &mut connection,
            Role::Operator,
            "operator",
            "{\"schemaVersion\":1,\"usedGrams\":1000}",
            &[notice("filament.milestone"), notice("filament.reserve")],
            2,
        );
        assert!(result.unwrap_err().contains("forced chain failure"));
        assert_eq!(stored(&connection), old);
        assert_eq!(count(&connection, "audit"), 0);
        assert_eq!(count(&connection, "audit_chain"), 0);
        let updated_at: i64 = connection
            .query_row("SELECT updated_at FROM kv WHERE key=?1", [INVENTORY_KEY], |row| row.get(0))
            .unwrap();
        assert_eq!(updated_at, 1);
        assert!(connection.is_autocommit());
    }

    #[test]
    fn filament_inventory_viewer_cannot_write_or_emit_notices() {
        let mut connection = database();
        let error = commit_inventory(
            &mut connection,
            Role::Viewer,
            "viewer",
            "{\"schemaVersion\":1}",
            &[notice("filament.reserve")],
            1,
        )
        .unwrap_err();
        assert!(error.starts_with("FORBIDDEN:"));
        assert_eq!(count(&connection, "kv"), 0);
        assert_eq!(count(&connection, "audit"), 0);
        assert_eq!(count(&connection, "audit_chain"), 0);
    }

    #[test]
    fn filament_inventory_invalid_or_oversized_input_never_mutates_database() {
        let mut connection = database();
        let oversized = format!("{{\"schemaVersion\":1,\"data\":\"{}\"}}", "x".repeat(MAX_INVENTORY_BYTES));
        for value in ["{", "null", "[]", "{}", "{\"schemaVersion\":2}", "{\"schemaVersion\":\"1\"}", &oversized] {
            assert!(commit_inventory(&mut connection, Role::Operator, "operator", value, &[], 1).is_err());
        }
        for notices in [
            vec![notice("print.complete")],
            vec![FilamentNotice { action: "filament.reserve".into(), details: " ".into() }],
            vec![FilamentNotice { action: "filament.reserve".into(), details: "я".repeat(MAX_NOTICE_BYTES) }],
            (0..=MAX_NOTICES).map(|_| notice("filament.reserve")).collect(),
        ] {
            assert!(commit_inventory(&mut connection, Role::Operator, "operator", "{\"schemaVersion\":1}", &notices, 1).is_err());
        }
        assert_eq!(count(&connection, "kv"), 0);
        assert_eq!(count(&connection, "audit"), 0);
        assert_eq!(count(&connection, "audit_chain"), 0);
    }
}

