    timer=window.setTimeout(async()=>{await run('startup');if(!stopped)schedule()},15_000);
    networkTimer=window.setTimeout(pollNetwork,250);
    const resume=()=>{if(!networkPolling&&!document.hidden&&Date.now()-networkHeartbeat.current>10_000)markNetworkTransition('resume')};
    window.addEventListener('focus',resume);window.addEventListener('online',resume);document.addEventListener('visibilitychange',resume);
    return()=>{stopped=true;if(timer)window.clearTimeout(timer);if(networkTimer)window.clearTimeout(networkTimer);const operationId=discoveryRecheckOperation.current;if(operationId)void secureInvoke<boolean>('cancel_moonraker_discovery',{operationId}).catch(()=>false);window.removeEventListener('focus',resume);window.removeEventListener('online',resume);document.removeEventListener('visibilitychange',resume)};
  },[isAdmin,printerConfigReady,showDiscovery]);
  const updateConfig=async(cfg:PrinterConfig)=>{
