const text=(value:unknown,maximum:number)=>typeof value==='string'?value.trim().slice(0,maximum):'';

/** Only printer-reported usage enters accounting. Slicer estimates never fill missing counters. */
export function filamentHistoryObservation(job:HistoryJob,printer:Pick<PrinterModel,'id'|'name'>):FilamentJobObservation{
  const used=finiteNumber(job.filament_used);
  const metadata=job.metadata&&typeof job.metadata==='object'?job.metadata:{};
  return{
    printerId:printer.id,
    printerName:printer.name,
    jobId:typeof job.job_id==='string'&&job.job_id.trim().length<=160?job.job_id.trim():'',
    filename:text(job.filename,2048),
    startTime:milliseconds(job.start_time)??0,
    endTime:milliseconds(job.end_time),
    status:text(job.status,64).toLowerCase(),
    usedMm:used!==undefined&&used>=0?used:undefined,
    material:text(metadata.filament_type,80)||undefined,
  };
}

/** Baseline reads the newest page. Normal reconciliation must finish every page before committing any usage. */
export async function collectFilamentHistory(client:HistoryReader,{sinceMs,baseline=false,signal}:{sinceMs?:number;baseline?:boolean;signal?:AbortSignal}={}):Promise<HistoryJob[]>{
  if(sinceMs!==undefined&&(!Number.isFinite(sinceMs)||sinceMs<0))throw new Error('Неизвестно начало учёта пластика; требуется повторная привязка материала');
  const jobs:HistoryJob[]=[];
  const pages=new Set<string>();
  let offset=0;
  // One empty probe after the bounded data pages also detects forks that clamp the requested page size.
  for(let pageNumber=0;pageNumber<=FILAMENT_HISTORY_MAX_PAGES;pageNumber++){
    abortIfNeeded(signal);
    const page=await client.historyPage({
      limit:FILAMENT_HISTORY_PAGE_SIZE,
      start:offset,
      since:baseline||sinceMs===undefined?undefined:Math.max(0,(sinceMs-1000)/1000),
      order:'desc',
      signal,
    });
    abortIfNeeded(signal);
    if(!Array.isArray(page.jobs)||page.jobs.length>FILAMENT_HISTORY_PAGE_SIZE)throw new Error('Некорректная история печати: автоматическое списание не выполнено');
    if(!page.jobs.length)return jobs;
    if(pageNumber===FILAMENT_HISTORY_MAX_PAGES)break;
    const fingerprint=JSON.stringify(page.jobs.map(job=>[job.job_id,job.start_time,job.filename]));
    if(page.jobs.length&&pages.has(fingerprint))throw new Error('Прошивка повторяет страницу истории; автоматическое списание не выполнено');
    pages.add(fingerprint);
    jobs.push(...page.jobs);
    offset+=page.jobs.length;
    if(baseline)return jobs;
  }
  throw new Error('История не поместилась в 20 страниц (до 2000 заданий). Автоматическое списание приостановлено; проверьте расход и подтвердите остаток вручную');
}

/** A retained/stale counter cannot establish the already-used portion of an active print. */
export function activeFilamentBaseline(printer:PrinterModel,jobs:HistoryJob[],now=Date.now()):{filename:string;usedMm?:number;startedAt?:number}|undefined{
  const activeRows=jobs.filter(job=>String(job.status??'').toLowerCase()==='in_progress');
  const active=printer.status.state==='printing'||printer.status.state==='paused';
  const filename=printer.status.filename?.trim()||(!active&&activeRows.length===1?activeRows[0].filename?.trim():undefined);
  if(!filename)return undefined;
  const matching=activeRows.filter(job=>job.filename?.trim()===filename);
  if(!active&&!matching.length)return undefined;
  const timestamp=printer.status.jobUpdatedAt;
  const fresh=printer.status.connectionState==='online'&&timestamp!==undefined&&timestamp<=now+2000&&now-timestamp<=20_000;
  const counter=printer.status.filamentUsedMm;
  const valid=active&&fresh&&activeRows.length===1&&matching.length===1&&!!text(matching[0].job_id,160)&&milliseconds(matching[0].start_time)!==undefined&&counter!==undefined&&Number.isFinite(counter)&&counter>=0;
  return{filename,usedMm:valid?counter:undefined,startedAt:matching.length===1?milliseconds(matching[0].start_time):undefined};
}

