const MAX_STATE_BYTES=2*1024*1024;
const listeners=new Set<(state:FilamentInventory)=>void>();
let chain:Promise<unknown>=Promise.resolve();
let provisional:{legacy:string;state:FilamentInventory}|undefined;
function serial<T>(run:()=>Promise<T>):Promise<T>{const operation=chain.then(run);chain=operation.catch(()=>{});return operation}
const copy=(state:FilamentInventory):FilamentInventory=>JSON.parse(JSON.stringify(state)) as FilamentInventory;
async function strictRead(key:string):Promise<unknown|null>{
  const raw=await secureInvoke<string|null>('db_get_json',{key});
  if(raw===null)return null;
  if(typeof raw!=='string')throw new Error('Хранилище пластика вернуло неподдерживаемый ответ.');
  try{return JSON.parse(raw) as unknown}catch{throw new Error('Сохранённые данные пластика повреждены. Остатки не изменены.');}
}
async function load():Promise<{state:FilamentInventory;persisted:boolean}>{
  const stored=await strictRead(FILAMENT_INVENTORY_KEY);
  if(stored!==null){provisional=undefined;return {state:restoreFilamentInventory(stored),persisted:true};}
  let legacy=await strictRead('production.spools');
  if(legacy===null){
    const raw=localStorage.getItem('klipper-spools-v06');
    if(raw!==null){try{legacy=JSON.parse(raw) as unknown}catch{throw new Error('Существующие катушки не удалось прочитать. Остатки не изменены.');}}
  }
  const encoded=JSON.stringify(legacy??[]);
  if(provisional?.legacy===encoded)return {state:copy(provisional.state),persisted:false};
  const state=legacy===null?emptyFilamentInventory():migrateFilamentInventory(legacy);
  provisional={legacy:encoded,state:copy(state)};
  // Viewing and migration preview never write: viewer sessions remain read-only.
  return {state,persisted:false};
}
export function readFilamentInventory():Promise<FilamentInventory>{return serial(async()=>copy((await load()).state));}
export function subscribeFilamentInventory(listener:(state:FilamentInventory)=>void):()=>void{listeners.add(listener);return()=>listeners.delete(listener);}
export function updateFilamentInventory(command:FilamentCommand):Promise<FilamentInventory>{
  return serial(async()=>{
    const loaded=await load(),previous=loaded.state,result=reduceFilamentInventory(previous,command),encoded=JSON.stringify(result.state);
    if(loaded.persisted&&!result.notices.length&&JSON.stringify(previous)===encoded)return copy(previous);
    if(new TextEncoder().encode(encoded).byteLength>MAX_STATE_BYTES)throw new Error('Журнал учёта пластика достиг предела хранения. Списание остановлено; сохранённые остатки и итоги не изменены.');
    // The native transaction stores state and durable bell entries together.
    await secureInvoke('filament_inventory_commit',{value:encoded,notices:result.notices.map(({action,details})=>({action,details}))});
    provisional=undefined;
    for(const listener of listeners){try{listener(copy(result.state));}catch(reason){diagnosticWarning('filament.subscriber',reason);}}
    if(result.notices.length)window.dispatchEvent(new Event(NOTIFICATION_REFRESH));
    for(const notice of result.notices){
      showAppNotification(notice.title,notice.body,notice.action==='filament.reserve'?'danger':'info',{dedupeKey:`${notice.action}:${notice.details}`,expiresAfterMs:12_000});
      void nativeNotify(notice.title,notice.body).catch(reason=>diagnosticWarning('filament.native_notification',reason));
    }
    return copy(result.state);
  });
}

