  async upload(file:File,onProgress?:(percent:number)=>void,externalSignal?:AbortSignal):Promise<string>{
    if(file.size>100*1024*1024)throw new Error('G-code превышает лимит 100 MiB');
    if(file.size===0)throw new Error('G-code пуст');
    if(this.uploadInFlight)throw new Error('На этот принтер уже загружается G-code');
    if(externalSignal?.aborted)throw new RequestCancelledError('Загрузка отменена');
    const controller=new AbortController();
    const externalAbort=()=>controller.abort(externalSignal?.reason);
    externalSignal?.addEventListener('abort',externalAbort,{once:true});
    this.uploadController=controller;
    const task=this.runFileTransfer(async signal=>{
      const ensureActive=()=>{if(signal.aborted)throw new RequestCancelledError('Загрузка отменена пользователем')};
      ensureActive();
      onProgress?.(1);
      const expectedSha256=await blobSha256(file);
      ensureActive();
      onProgress?.(3);
      const started=await secureInvoke<NativeUploadBegin>('transactional_upload_begin',{
        ...this.uploadTarget(),
        filename:file.name,
        fileSize:file.size,
        expectedSha256,
      });
      this.activeUploadId=started.uploadId;
      if(started.completedPath){
        this.uploadedHashes.set(started.completedPath,expectedSha256);
        this.uploadedFiles.set(started.completedPath,file);
        this.activeUploadId=undefined;
        onProgress?.(100);
        return started.completedPath;
      }
      const chunkSize=Math.max(64*1024,Math.min(512*1024,Math.trunc(started.chunkSize)||512*1024));
      let offset=Math.max(0,Math.min(file.size,Math.trunc(started.receivedSize)||0)),finished=false;
      if(offset>0)onProgress?.(Math.max(3,Math.min(94,Math.round(offset/file.size*91)+3)));
      try{
        while(offset<file.size){
          ensureActive();
          const end=Math.min(file.size,offset+chunkSize);
          const data=Array.from(new Uint8Array(await file.slice(offset,end).arrayBuffer()));
          ensureActive();
          const received=await secureInvoke<number>('transactional_upload_chunk',{uploadId:started.uploadId,offset,data});
          if(received!==end)throw new Error('Staging-журнал подтвердил неверный размер блока G-code');
          offset=end;
          onProgress?.(Math.max(3,Math.min(94,Math.round(offset/file.size*91)+3)));
        }
        ensureActive();
        onProgress?.(95);
        const result=await secureInvoke<NativeUploadFinish>('transactional_upload_finish',{uploadId:started.uploadId});
        finished=true;
        this.uploadedHashes.set(result.path,result.sha256);
        this.uploadedFiles.set(result.path,file);
        while(this.uploadedHashes.size>32)this.uploadedHashes.delete(this.uploadedHashes.keys().next().value as string);
        while(this.uploadedFiles.size>8)this.uploadedFiles.delete(this.uploadedFiles.keys().next().value as string);
        this.invalidateFileCaches(result.path);
        onProgress?.(100);
        return result.path;
      }finally{
        if(this.activeUploadId===started.uploadId)this.activeUploadId=undefined;
        // Transport errors preserve the staged file for resume. Only an
        // explicit user cancellation destroys the resumable transaction.
        if(!finished&&signal.aborted)await secureInvoke<boolean>('transactional_upload_abort',{uploadId:started.uploadId}).catch(error=>{diagnosticWarning('moonraker.upload.abort',error,{printerId:this.config.id,operation:'upload.abort'});return false});
      }
    },controller.signal,'upload.gcode');
    this.uploadInFlight=task;
    try{return await task}
    finally{
      externalSignal?.removeEventListener('abort',externalAbort);
      if(this.uploadInFlight===task)this.uploadInFlight=undefined;
      if(this.uploadController===controller)this.uploadController=undefined;
    }
  }
  cancelUpload(){if(!this.uploadController)return false;this.uploadController.abort('Загрузка отменена пользователем');return true}
  uploadActive(){return!!this.uploadController}
  uploadedSha256(filename:string){return this.uploadedHashes.get(filename)}
  uploadedFile(filename:string){return this.uploadedFiles.get(filename)}
}

import { useEffect, useRef } from 'react';
import type { PrinterModel } from '../types';
import type { MoonrakerClient } from './moonraker';
import { filamentJobKey, type FilamentInventory } from './filamentInventory';
import { readFilamentInventory, subscribeFilamentInventory, updateFilamentInventory } from './filamentInventoryStore';
import { activeFilamentBaseline, collectFilamentHistory, filamentHistoryObservation, FILAMENT_ACCOUNTING_REFRESH_EVENT } from './filamentHistory';
import { diagnosticWarning } from './diagnosticLog';

const POLL_INTERVAL=60_000;
export const FILAMENT_ACCOUNTING_ERROR_EVENT='klipper-filament-accounting-error';
const bindingSignature=(inventory:FilamentInventory)=>Object.entries(inventory.printers)
  .map(([printerId,value])=>`${printerId}:${value.binding?.id??''}`).sort().join('|');
const errorMessage=(error:unknown)=>String(error instanceof Error?error.message:error).slice(0,700);
const unsupportedHistory=(error:unknown)=>/(?:HTTP(?: error| response)?[: ]+)?(?:404|405)\b|method not found|unknown (?:method|endpoint)|history (?:is )?(?:not available|disabled)/i.test(errorMessage(error));

/** Mount once for an authenticated operator. Telemetry renders only refresh refs, never issue requests. */
export function useFilamentAccounting({enabled,printers,clients}:{enabled:boolean;printers:PrinterModel[];clients:Map<string,MoonrakerClient>}){
  const printersRef=useRef(printers),clientsRef=useRef(clients);
  printersRef.current=printers;
  clientsRef.current=clients;
  const identity=printers.map(printer=>`${printer.id}:${printer.host}`).sort().join('|');
  useEffect(()=>{
    if(!enabled)return;
    let stopped=false,inFlight=false,refreshPending=false,timer:number|undefined,lastBindings='';
    const controller=new AbortController();
    const active=()=>!stopped&&!controller.signal.aborted;
    const schedule=(delay:number)=>{
      if(!active())return;
      if(inFlight){refreshPending=true;return}
      if(timer!==undefined)window.clearTimeout(timer);
      timer=window.setTimeout(()=>{timer=undefined;void tick()},delay);
    };
    const persistFailure=async(printerId:string,error:unknown)=>{
      if(!active())return;
      await updateFilamentInventory({type:'set-printer-status',printerId,status:unsupportedHistory(error)?'no-history':'error',message:errorMessage(error)});
    };
    const reconcile=async(printerId:string)=>{
      if(!active())return;
      const inventory=await readFilamentInventory();
      if(!active())return;
      const account=inventory.printers[printerId],binding=account?.binding;
      if(!binding)return;
      const printer=printersRef.current.find(value=>value.id===printerId),client=clientsRef.current.get(printerId);
      if(!printer||!client)return;
      if(printer.status.remoteControlSuspended||printer.status.connectionState!=='online'){
        await persistFailure(printerId,new Error('Нет связи с принтером. Расход будет сверён с историей после восстановления подключения'));
        return;
      }
      // Forge-X resource limits remain in force: ongoing accounting must not compete with a print.
      // The first baseline still needs its current counter before this print ends.
      if(!binding.baselinePending&&client.prefersLowResourceMode()&&(printer.status.state==='printing'||printer.status.state==='paused'))return;
      const jobs=await collectFilamentHistory(client,{baseline:binding.baselinePending,sinceMs:binding.baselinePending?undefined:account.reconcileSince??account.trackingAt,signal:controller.signal});
      if(!active())return;
      const observations=jobs.map(job=>filamentHistoryObservation(job,printer));
      if(binding.baselinePending){
        const live=printersRef.current.find(value=>value.id===printerId);
        if(!live)return;
        await updateFilamentInventory({type:'history-baseline',printerId,bindingId:binding.id,at:Date.now(),jobs:observations,active:activeFilamentBaseline(live,jobs)});
      }else{
        // The complete read succeeded. A partial/failed page batch cannot submit any new debits.
        observations.sort((left,right)=>left.startTime-right.startTime||left.jobId.localeCompare(right.jobId));
        let latestInventory=inventory;
        for(const job of observations){
          if(!active())return;
          if(job.status==='in_progress')continue;
          const key=filamentJobKey(job),marker=key?latestInventory.processedJobs[key]:undefined;
          if(marker&&(marker.outcome!=='charged'||job.usedMm===undefined||marker.usedMm!==undefined&&job.usedMm<=marker.usedMm))continue;
          latestInventory=await updateFilamentInventory({type:'observe-job',job});
        }
        if(!active())return;
        // Advance only after the complete batch is durably accounted. The reducer retains active jobs and an overlap.
        await updateFilamentInventory({type:'history-reconciled',printerId,bindingId:binding.id,from:account.reconcileSince,jobs:observations});
      }
      if(!active())return;
      const current=await readFilamentInventory();
      const latest=current.printers[printerId];
      if(active()&&latest?.binding?.id===binding.id&&!latest.binding.baselinePending&&!latest.pendingJobs)await updateFilamentInventory({type:'set-printer-status',printerId,status:'tracking'});
    };
    const reportError=(error:unknown)=>{
      if(!active()||error instanceof Error&&error.name==='AbortError')return;
      diagnosticWarning('filament.accounting',error);
      window.dispatchEvent(new CustomEvent(FILAMENT_ACCOUNTING_ERROR_EVENT,{detail:errorMessage(error)}));
    };
    const tick=async()=>{
      if(!active()||inFlight)return;
      inFlight=true;
      refreshPending=false;
      try{
        const inventory=await readFilamentInventory();
        if(!active())return;
        lastBindings=bindingSignature(inventory);
        const ids=Object.keys(inventory.printers).filter(id=>inventory.printers[id].binding&&printersRef.current.some(printer=>printer.id===id));
        let cursor=0;
        await Promise.all(Array.from({length:Math.min(2,ids.length)},async()=>{
          while(active()&&cursor<ids.length){
            const printerId=ids[cursor++];
            try{await reconcile(printerId)}
            catch(error){
              if(!active())return;
              try{await persistFailure(printerId,error)}catch(persistenceError){reportError(persistenceError)}
            }
          }
        }));
      }catch(error){reportError(error)}
      finally{
        inFlight=false;
        if(active())schedule(refreshPending?0:POLL_INTERVAL);
      }
    };
    const unsubscribe=subscribeFilamentInventory(inventory=>{
      if(!active())return;
      const next=bindingSignature(inventory);
      if(next!==lastBindings){lastBindings=next;schedule(0)}
    });
    const refresh=()=>schedule(0);
    window.addEventListener(FILAMENT_ACCOUNTING_REFRESH_EVENT,refresh);
    schedule(1000);
    return()=>{
      stopped=true;
      controller.abort();
      unsubscribe();
      window.removeEventListener(FILAMENT_ACCOUNTING_REFRESH_EVENT,refresh);
      if(timer!==undefined)window.clearTimeout(timer);
    };
  },[enabled,identity]);
}

