 async function pageFor(query='',theme='light',width=1536,height=1000){
  const page=await browser.newPage({viewport:{width,height},locale:'ru-RU'});currentPage=page;
  page.on('pageerror',error=>runtimeErrors.push(error.message));
  await page.route('**/*',route=>route.request().url().startsWith(origin+'/')?route.continue():route.abort());
  await page.goto(`${origin}/ui-tests/filament-inventory.html?theme=${theme}&${query}`);
  return page;
 }
 const panel=page=>page.getByRole('region',{name:'Запас и расход пластика',exact:true});
 const form=page=>panel(page).locator('form');
 const material=(page,name)=>page.getByTestId('filament-material-'+name);
 const printer=(page,id)=>page.getByTestId('filament-printer-'+id);
 async function loaded(page){await panel(page).getByRole('button',{name:'Добавить пластик',exact:true}).waitFor()}
 async function state(page){return await page.evaluate(()=>window.__inventory())}
 async function db(page){return await page.evaluate(()=>window.__database())}
 async function notices(page){return await page.evaluate(()=>window.__notices())}
 async function commits(page){return await page.evaluate(()=>window.__calls.filter(call=>call.command==='filament_inventory_commit').length)}
 async function total(page,name){const value=await state(page);return (value.materials[name]?.looseGrams??0)+value.spools.filter(spool=>spool.material===name).reduce((sum,spool)=>sum+spool.remainingWeight,0)}
 async function save(page,label='Сохранить'){await form(page).getByRole('button',{name:label,exact:true}).click();await form(page).waitFor({state:'detached'})}
 async function addStock(page,name,quantity,reserve){
  await panel(page).getByRole('button',{name:'Добавить пластик',exact:true}).click();
  await form(page).getByLabel('Материал',{exact:true}).selectOption(name);
  await form(page).getByLabel('Добавить на склад, кг',{exact:true}).fill(quantity);
  if(reserve!==undefined)await form(page).getByLabel(/^Резерв, кг/).fill(reserve);
  await save(page);
 }
 async function writeoff(page,id,name,quantity){
  await printer(page,id).getByRole('button',{name:'Расход вручную',exact:true}).click();
  await form(page).getByLabel('Материал',{exact:true}).selectOption(name);
  await form(page).getByLabel('Откуда списывать',{exact:true}).selectOption('');
  await form(page).getByLabel('Расход, кг',{exact:true}).fill(quantity);
  await save(page,'Записать расход');
 }
 async function shot(page,name){if(shots)await page.screenshot({path:path.join(shots,'filament-'+name+'.png')})}
 async function noOverflow(page){
  const value=await page.evaluate(()=>({width:innerWidth,document:document.documentElement.scrollWidth,body:document.body.scrollWidth}));
  assert.ok(value.document<=value.width+1&&value.body<=value.width+1,'Filament UI overflows horizontally: '+JSON.stringify(value));
  const fields=await form(page).locator('input,select,button').evaluateAll(elements=>elements.filter(element=>{const s=getComputedStyle(element);return s.display!=='none'&&s.visibility!=='hidden'}).map(element=>{const b=element.getBoundingClientRect();return {left:b.left,right:b.right,label:element.getAttribute('aria-label')||element.textContent||element.tagName}}));
  for(const field of fields)assert.ok(field.left>=-.5&&field.right<=value.width+.5,'Unreachable inventory form control: '+JSON.stringify(field));
 }
 async function nativeBoundariesOnly(page){
  const calls=await page.evaluate(()=>window.__calls);
  for(const call of calls){
   assert.ok(['db_get_json','db_set_json','filament_inventory_commit','native_notify','notification_list','audit_add'].includes(call.command),'Inventory interaction attempted printer control: '+call.command);
   if(call.command==='db_set_json')assert.ok(!['production.filamentInventory','production.spools'].includes(call.args.key),'Inventory bypassed atomic persistence');
  }
 }

